  function lagrange(u, k) {            /* six-point Lagrange through nodes k-2 .. k+3, u = fractional index */
    var out = [0, 0, 0], i, j, m, w, t = u - k;
    for (j = -2; j <= 3; j++) {
      w = 1;
      for (m = -2; m <= 3; m++) if (m !== j) w *= (t - m) / (j - m);
      for (i = 0; i < 3; i++) out[i] += w * D.p[(k + j) * 3 + i];
    }
    return [out[0] * D.q, out[1] * D.q, out[2] * D.q];
  }
  function helio(jd) {
    var u = (jd - D.jd0) / D.step, k = Math.floor(u);
    if (k < 2 || k > D.n - 4) return null;
    return lagrange(u, k);
  }

